#include <tamtypes.h>
#include <kernel.h>
#include <sifrpc.h>
#include <libcdvd.h>
#include <debug.h>
#include <string.h>
#include <strings.h>
#include "iso.h"
#include "avi.h"
static int sector(uint32_t lba,void *p){sceCdRMode m={0};m.trycount=3;m.spindlctrl=1;m.datapattern=0;if(!sceCdRead(lba,1,p,&m))return 0;sceCdSync(0);return sceCdGetError()==0;}
int main(void){IsoFile root,dir,f;char name[256];unsigned char h[12],block[4096];int r,n=0;init_scr();SetGsCrt(1,2,1);scr_printf("DG MOVIE V0.1.3 - DIAGNOSTICO\nNTSC 60Hz / sem reset IOP\n");SifInitRpc(0);scr_printf("RPC OK\n");sceCdInit(SCECdINIT);scr_printf("CD INIT retornou\n");if(!iso_mount(sector,&root)){scr_printf("FALHA PVD ISO9660\n");goto end;}scr_printf("PVD OK\n");{IsoFile scan=root; int count=0; while((r=iso_next(&scan,&f,name))>0 && count<8){scr_printf("ROOT %s %s\n",(f.flags&2)?"DIR":"FILE",name);count++;} scr_printf("ROOT scan: %d\n",r); } if((iso_open(root,"MOVIES",&dir)!=1||!(dir.flags&2))&&(iso_open(root,"FILMES",&dir)!=1||!(dir.flags&2))){if(iso_mount_joliet(&root)&&iso_open(root,"MOVIES",&dir)==1&&(dir.flags&2)){scr_printf("MOVIES JOLIET OK\n");}else{iso_mount(sector,&root);dir=root;scr_printf("MOVIES ausente; testando raiz\n");}}else scr_printf("PASTA ISO OK\n");while((r=iso_next(&dir,&f,name))>0){char *ext=strrchr(name,'.');if(f.flags&2||!ext||(strcasecmp(ext,".AVI")&&strcasecmp(ext,".MP4")))continue;scr_printf("%s LBA:%u bytes:%u\n",name,f.lba,f.size);if(iso_read(&f,h,12)!=12){scr_printf("FALHA leitura cabecalho\n");continue;}scr_printf("Header: %s\n",!memcmp(h,"RIFF",4)&&!memcmp(h+8,"AVI ",4)?"AVI RIFF":!memcmp(h+4,"ftyp",4)?"MP4 FTYP":"OUTRO");if(f.size>=sizeof(block)&&iso_seek(&f,f.size/2)&&iso_read(&f,block,sizeof(block))==(int)sizeof(block))scr_printf("Seek meio + 4096 bytes OK\n");else scr_printf("Seek/leitura FALHOU\n");if(!strcasecmp(ext,".AVI")){AviInfo a;if(avi_scan(f,&a)){scr_printf("AVI %ux%u %u/%u fps\n",a.width,a.height,a.rate,a.scale);scr_printf("Codec %c%c%c%c audio 0x%x\n",a.codec&255,(a.codec>>8)&255,(a.codec>>16)&255,a.codec>>24,a.format);scr_printf("Audio %u Hz %u canais\n",a.hz,a.channels);scr_printf("Video: %u blocos %u bytes\n",a.frames,a.video_bytes);scr_printf("Audio: %u blocos %u bytes\n",a.audio_blocks,a.audio_bytes);}else scr_printf("FALHA DEMUX AVI\n");}if(++n>=1)break;}scr_printf("Fim: %d filmes, estado %d\n",n,r);end:scr_printf("Fotografe esta tela. Sem reproducao nesta build.\n");SleepThread();return 0;}
